import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val text = BufferedReader(InputStreamReader(System.`in`)).readText()
    val arr = ArrayDeque(text.split("\n"))

    val ax = arr.removeFirst().split(" ")
    val v = ax[0].trim().toInt()
    val e = ax[1].trim().toInt()

    if (e == 0) {
        println(0)
        return
    }
    if (v <= 6) {
        println(e)
    } else {
        val m = HashMap<Int, MutableList<Int>>()

        for (i in 1..v) {
            m[i] = mutableListOf()
        }

        for (i in 0 until e) {
            val edge = arr.removeFirst().trim().split(" ")
            val a = edge[0].toInt()
            val b = edge[1].toInt()
            m[a]!!.add(b)
            m[b]!!.add(a)
        }

        var f = false
        var noOfVertices = 20
        for (j in 1..7) {
            val a7 = m[j]!!
            for (i in 1..7) {
                if (i == j) continue
                val other = m[i]!!
                val x = a7.filter { other.indexOf(it) != -1 }
                if (x.isEmpty()) {
                    f = true
                    break
                } else if (x.size < noOfVertices) {
                    noOfVertices = x.size
                }
            }
        }
        if (f) {
            println(e)
        } else {
            println(e - noOfVertices)
        }
    }
}
